// Rujukan $('Nama Node') ditulis eksplisit agar task runner n8n mengirim data node tersebut.
const __nyata = { "Terima Pertanyaan": () => $('Terima Pertanyaan'), "Baca Semua Sheet": () => $('Baca Semua Sheet'), "Lanjut?": () => $('Lanjut?'), "Kirim Respons Awal": () => $('Kirim Respons Awal'), "Tanya Claude": () => $('Tanya Claude'), "Periksa & Susun Draf": () => $('Periksa & Susun Draf'), "Perlu Draf?": () => $('Perlu Draf?'), "Tanya Claude (Draf)": () => $('Tanya Claude (Draf)'), "Simpan Jawaban": () => $('Simpan Jawaban'), "Tulis Semua Sheet": () => $('Tulis Semua Sheet'), "Kirim Jawaban": () => $('Kirim Jawaban'), "Catat Gagal": () => $('Catat Gagal'), "Tulis Log Error": () => $('Tulis Log Error'), "Kirim Respons Gagal": () => $('Kirim Respons Gagal') };
const __asli = (n) => (n in __nyata ? __nyata[n]() : $(n));
const __peta = {"Ambil Teks Model": "Periksa & Susun Draf", "Periksa Jawaban": "Periksa & Susun Draf", "Susun Prompt Draf": "Periksa & Susun Draf", "Ambil Teks Draf": "Simpan Jawaban", "Periksa Draf": "Simpan Jawaban", "Cek Mode Gagal": "Simpan Jawaban", "Siapkan Penulisan": "Simpan Jawaban", "Siapkan Log Error": "Catat Gagal", "Data Log": "Catat Gagal", "Susun Baris Log": "Catat Gagal"};
const __lokal = ["Validasi Masukan", "Olah Data Sheet", "Cek Permintaan Lama", "Cari Prospek", "Susun Prompt"];
const __hasil = {};
const __tidakJalan = (n) => ({ isExecuted: false, first: () => { throw new Error('Langkah ' + n + ' tidak dijalankan.'); }, all: () => [] });
function __ref(n) {
  if (n in __hasil) return { isExecuted: true, first: () => __hasil[n][0], all: () => __hasil[n] };
  if (__lokal.includes(n)) return __tidakJalan(n);
  if (n in __peta) {
    const nyata = __asli(__peta[n]);
    if (!nyata.isExecuted) return __tidakJalan(n);
    const j = (nyata.first().json.__langkah || {})[n];
    if (j === undefined) return __tidakJalan(n);
    return { isExecuted: true, first: () => ({ json: j }), all: () => [{ json: j }] };
  }
  return __asli(n);
}
const __masuk = (items) => ({ first: () => items[0], all: () => items });
function __jalan(nama, fn, items) {
  try {
    const out = fn(__ref, __masuk(items));
    __hasil[nama] = out;
    return out;
  } catch (e) {
    e.message = '[' + nama + '] ' + e.message;
    throw e;
  }
}
const __selesai = (json) => [{
  json: { ...json, __langkah: Object.fromEntries(Object.entries(__hasil).map(([k, v]) => [k, v[0] && v[0].json])) },
}];
